commands.expression:
Alert.findOneAndUpdate(
          {
            _id: req.params.id,
            business: business._id,
            resolvedAt: null,
          },
          { $set: assignmentUpdate },
          { returnDocument: "after", runValidators: true },
        )

Alert.findOneAndUpdate(
          {
            _id: req.params.id,
            business: business._id,
            resolvedAt: null,
            acknowledgedAt: null,
          },
          { $set: set },
          { returnDocument: "after", runValidators: true },
        )

Alert.findOneAndUpdate(
          {
            _id: req.params.id,
            business: business._id,
            resolvedAt: null,
          },
          { $set: set },
          { returnDocument: "after", runValidators: true },
        )

Conversation.findOneAndUpdate({
      _id: normalizeId(alert.conversation), business: business._id,
    }, { $set: { humanTakeover: true, aiEnabled: false } }, { returnDocument: 'after' })

model
        .findOneAndUpdate(
          {
            owner: ownerId,
          },
          data,
          {
            returnDocument: "after",
            runValidators: true,
          },
        )

model
        .findOneAndUpdate(
          { _id: userId },
          [
            {
              $set: {
                _existingFailureCount: {
                  $cond: [
                    {
                      $and: [
                        { $ne: ["$lastFailedLoginAt", null] },
                        {
                          $gte: ["$lastFailedLoginAt", observationWindowStart],
                        },
                      ],
                    },
                    { $ifNull: ["$failedLoginAttempts", 0] },
                    0,
                  ],
                },

                _existingLockoutLevel: {
                  $cond: [
                    {
                      $or: [
                        { $eq: ["$lastFailedLoginAt", null] },
                        {
                          $lt: ["$lastFailedLoginAt", decayWindowStart],
                        },
                      ],
                    },
                    0,
                    { $ifNull: ["$loginLockoutLevel", 0] },
                  ],
                },
              },
            },

            {
              $set: {
                _nextFailureCount: {
                  $add: ["$_existingFailureCount", 1],
                },
              },
            },

            {
              $set: {
                _shouldBlock: {
                  $gte: ["$_nextFailureCount", 5],
                },

                _nextLockoutLevel: {
                  $cond: [
                    { $gte: ["$_nextFailureCount", 5] },
                    { $add: ["$_existingLockoutLevel", 1] },
                    "$_existingLockoutLevel",
                  ],
                },
              },
            },

            {
              $set: {
                _delayMinutes: {
                  $switch: {
                    branches: [
                      {
                        case: {
                          $eq: ["$_nextLockoutLevel", 1],
                        },
                        then: 1,
                      },
                      {
                        case: {
                          $eq: ["$_nextLockoutLevel", 2],
                        },
                        then: 5,
                      },
                      {
                        case: {
                          $eq: ["$_nextLockoutLevel", 3],
                        },
                        then: 15,
                      },
                      {
                        case: {
                          $eq: ["$_nextLockoutLevel", 4],
                        },
                        then: 30,
                      },
                    ],
                    default: 60,
                  },
                },
              },
            },

            {
              $set: {
                failedLoginAttempts: {
                  $cond: ["$_shouldBlock", 0, "$_nextFailureCount"],
                },

                lastFailedLoginAt: now,

                loginLockoutLevel: "$_nextLockoutLevel",

                loginBlockedUntil: {
                  $cond: [
                    "$_shouldBlock",
                    {
                      $dateAdd: {
                        startDate: now,
                        unit: "minute",
                        amount: "$_delayMinutes",
                      },
                    },
                    {
                      $cond: [
                        {
                          $and: [
                            {
                              $ne: ["$loginBlockedUntil", null],
                            },
                            {
                              $gt: ["$loginBlockedUntil", now],
                            },
                          ],
                        },
                        "$loginBlockedUntil",
                        null,
                      ],
                    },
                  ],
                },

                lastLoginLockoutAt: {
                  $cond: ["$_shouldBlock", now, "$lastLoginLockoutAt"],
                },

                securityChallengeRequired: {
                  $or: [
                    {
                      $eq: [
                        {
                          $ifNull: ["$securityChallengeRequired", false],
                        },
                        true,
                      ],
                    },
                    {
                      $gte: ["$_nextLockoutLevel", 3],
                    },
                  ],
                },

                securityChallengeRequiredAt: {
                  $cond: [
                    {
                      $and: [
                        "$_shouldBlock",
                        {
                          $gte: ["$_nextLockoutLevel", 3],
                        },
                        {
                          $ne: [
                            {
                              $ifNull: ["$securityChallengeRequired", false],
                            },
                            true,
                          ],
                        },
                      ],
                    },
                    now,
                    "$securityChallengeRequiredAt",
                  ],
                },
              },
            },

            {
              $unset: [
                "_existingFailureCount",
                "_existingLockoutLevel",
                "_nextFailureCount",
                "_shouldBlock",
                "_nextLockoutLevel",
                "_delayMinutes",
              ],
            },
          ],
          {
            returnDocument: "after",
            updatePipeline: true,
          },
        )

model.findByIdAndUpdate(
        userId,
        {
          $set: {
            failedLoginAttempts: 0,
            lastFailedLoginAt: null,
            loginBlockedUntil: null,
            loginLockoutLevel: 0,
            lastLoginLockoutAt: null,
            securityChallengeRequired: false,
            securityChallengeRequiredAt: null,
            lastSuccessfulLoginAt: new Date(),
          },
        },
        {
          returnDocument: "after",
        },
      )

model.findOneAndUpdate(
        {
          _id: userId,
          lastFailedLoginAt: {
            $ne: null,
            $lt: decayWindowStart,
          },
        },
        {
          $set: {
            failedLoginAttempts: 0,
            lastFailedLoginAt: null,
            loginBlockedUntil: null,
            loginLockoutLevel: 0,
            lastLoginLockoutAt: null,
            securityChallengeRequired: false,
            securityChallengeRequiredAt: null,
          },
        },
        {
          returnDocument: "after",
        },
      )

model
        .findOneAndUpdate(
          { business: businessId },
          {
            ...data,
            business: businessId,
          },
          {
            returnDocument: "after",
            upsert: true,
            runValidators: true,
            setDefaultsOnInsert: true,
          },
        )

model
        .findOneAndUpdate({ stripeSubscriptionId }, data, {
          returnDocument: "after",
          runValidators: true,
        })

Conversation.updateOne(
    { _id: conversationId, business: businessId },
    {
      $set: {
        humanTakeover: true,
        aiEnabled: false,
        ...bookingTransitionFields('human_escalation_requested', { lastError: reason }),
      },
    },
  )

Alert.findOneAndUpdate({
            _id: existing._id, business: businessId, resolvedAt: { $ne: null },
            'metadata.serviceEligibilityReason': { $exists: true },
          }, {
            $set: {
              actionRequired: true, resolvedAt: null, resolvedBy: null,
              resolution: '', status: 'sent', assignedTo: null,
              acknowledgedAt: null, acknowledgedBy: null,
              dueAt: dueAt || staffReviewDueAt(normalizePriority(priority), reopenedAt),
              title, message, reason: truncate(reason, 1000),
              recommendedAction: truncate(recommendedAction, 1000),
              'metadata.serviceEligibilityReason': metadata.serviceEligibilityReason,
            },
            $unset: { 'metadata.workflow': 1 },
            $push: { reviewEvents: {
              key: `service-review-reopened:${reopenedAt.getTime()}`,
              occurredAt: reopenedAt, title: 'Customer renewed the service review request',
              message: 'The previous review remains in history; staff must make a new decision.',
            } },
          }, { returnDocument: 'after', runValidators: true })

Appointment.findOneAndUpdate(
        {
          _id: appointmentId,
          business: business._id,
          status: "confirmed",
        },
        {
          $set: { customerConfirmedAt: new Date() },
        },
        { returnDocument: "after" },
      )

conversation.orchestration = { ...(conversation.orchestration?.toObject?.() || conversation.orchestration || {}),
        phase: 'handoff_pending', handoffStatus: 'pending_ack', handoffReason: 'scheduling_review',
        handoffRequestedAt: now, handoffAcknowledgedAt: null }

conversation.conversationMemory = { ...memory, recoveryIntake: {
      ...(memory.recoveryIntake || {}), journeyKey: conversation.orchestration?.recoveryJourneyKey || '',
      withdrawnAt: memory.recoveryIntake?.withdrawnAt || new Date(), withdrawalReason: text.slice(0, 500),
    } }

Lead.updateOne(
        { _id: lead._id, business: appointment.business, $or: [{ bookedAt: null }, { bookedAt: { $lte: appointment.confirmedAt || new Date() } }] },
        {
          $set: {
            status: "booked",
            appointment: appointment._id,
            bookedAt: appointment.confirmedAt || new Date(),
            recovered,
            recoveredBy,
            // CALLBACKIQ_ATTRIBUTION_10OF10_FULL_V2:
            // the booked service/appointment is the authoritative open value.

          },
        },
      )

Alert.updateMany(
      {
        business: businessId,
        $or: [
          { lead: leadId },
          ...(conversationIds.length ? [{ conversation: { $in: conversationIds } }] : []),
          ...(appointmentIds.length ? [{ appointment: { $in: appointmentIds } }] : []),
        ],
      },
      { $set: { customerLifecycleStatus } },
    )

Alert.findOneAndUpdate({ ...eligible, dueAt: { $lte: now, $ne: null }, _id: candidate._id, business: candidate.business }, {
      $set: { priority: "critical", "metadata.reviewEscalatedAt": now },
    }, { returnDocument: "after", runValidators: true })

Lead.updateOne(
              {
                _id: leadId,
                business: businessId,
                $or: [
                  { firstTrackingNumber: null },
                  { firstTrackingNumber: { $exists: false } },
                ],
              },
              {
                $set: {
                  firstMarketingSource:
                    earliestCall?.marketingSource || marketingSource?._id || null,
                  firstTrackingNumber:
                    earliestCall?.trackingNumber || trackingNumber._id,
                  firstAttribution:
                    earliestCall?.attribution || attribution,
                },
              },
            )

Lead.updateOne(
          { _id: leadId, business: businessId },
          {
            $set: {
              latestMarketingSource: marketingSource?._id || null,
              latestTrackingNumber: trackingNumber?._id || null,
              latestAttribution: attribution,
            },
          },
        )

Conversation.updateOne(
        { _id: conversationId, business: businessId },
        {
          $set: {
            latestMarketingSource: marketingSource?._id || null,
            latestTrackingNumber: trackingNumber?._id || null,
            latestAttribution: attribution,
            ...(replyFromPhone ? { replyFromPhone } : {}),
          },
        },
      )

Conversation.findOneAndUpdate({
        _id: conversation._id, business: business._id,
        lead: conversation.lead || null, customerPhone: customerPhone,
      }, { $set: { lead: lead._id, ...bookingTransitionFields('conversation_lead_relinked'),
        "conversationMemory.recoveryIntake": {} }, $unset: { serviceEligibility: 1 } },
      { returnDocument: "after", runValidators: true })

Conversation.findByIdAndUpdate(
        conversation._id,
        {
          lastMessage: sent?.body || reply,
          lastMessageAt: new Date(),
        },
        { returnDocument: "after" },
      )

Conversation.findByIdAndUpdate(conversation._id, { $set: {
      'conversationMemory.recoveryIntake.contactControl.request': {
        kind: contactKind, alertId: String(saved.alert._id), inboundMessageId: String(inboundMessage._id),
        requestedAt: new Date(), callbackPhone: conversation.customerPhone,
      },
    } }, { returnDocument: 'after', runValidators: true })

Conversation.findByIdAndUpdate(conversation._id, { $set: {
      'conversationMemory.recoveryIntake.contactControl.receiptReply': {
        at: new Date(), inboundMessageId: String(inboundMessage._id),
      },
    } }, { runValidators: true })

Conversation.findOneAndUpdate(
    { _id: conversation._id, business: business._id },
    {
      $set: {
        aiEnabled: false,
        humanTakeover: true,
        humanTakeoverAt: new Date(),
        humanTakeoverBy: actorId,
        "orchestration.phase": "human_takeover",
        lastMessage: operation.metadata?.providerBody || operation.body,
        lastMessageAt: new Date(),
      },
    },
    { returnDocument: "after" },
  )

Conversation.findOneAndUpdate({
    _id: conversationId, business: businessId,
    status: 'open', humanTakeover: { $ne: true }, aiEnabled: { $ne: false },
    $or: [
      ...(operationKey ? [{ "orchestration.recoveryIntroOperationKey": operationKey }] : []),
      { 'orchestration.recoveryIntroClaimedAt': null },
      { 'orchestration.recoveryIntroClaimedAt': { $lte: cutoff } },
    ],
  }, { $set: { 'orchestration.recoveryIntroClaimedAt': now, ...(operationKey ? { 'orchestration.recoveryIntroOperationKey': operationKey } : {}) } }, { returnDocument: 'after' })

Conversation.findOneAndUpdate(
        {
          business: businessId,
          customerPhoneLookup: customerPhone,
          activeRecord: true,
        },
        {
          $setOnInsert: {
            business: businessId,
            lead: lead._id,
            customerPhone,
            customerPhoneLookup: customerPhone,
            customerName: lead.customerName,
            status: "open",
            activeRecord: true,
            aiEnabled: true,
            humanTakeover: false,
            "orchestration.recoveryJourneyKey": String(recoveryJourneyKey || "").trim(),
            "orchestration.recoveryJourneyStartedAt": new Date(),
            lastMessage: body || "Attachment received",
            lastMessageAt: new Date(),
          },
        },
        {
          upsert: true,
          returnDocument: "after",
          setDefaultsOnInsert: true,
          runValidators: true,
        },
      )

Conversation.findOneAndUpdate({
      _id: conversation._id, business: businessId, status: "closed",
      humanTakeover: { $ne: true }, aiEnabled: { $ne: false },
    }, { $set: { status: "open", reopenedAt: new Date(), reopenReason: "returning_customer_contact" } },
    { returnDocument: "after", runValidators: true })

Lead.updateOne({ _id: leadId, business: businessId, firstTrackingNumber: null, firstMarketingSource: null }, {
    $set: { firstMarketingSource: earliest.marketingSource || null,
      firstTrackingNumber: earliest.trackingNumber, firstAttribution: earliest.attribution || {} },
  })

Appointment.updateOne({ _id: original._id, business: appointment.business, status: 'confirmed' }, { $set: {
      status: 'rescheduled', rescheduledTo: appointment._id, activeSlotKey: null, slotClaimKeys: [], capacityLane: null,
      externalAppointmentId: null, externalCalendarId: null,
      ...(original.rescheduleRequest?.status === 'pending' ? { 'rescheduleRequest.status': 'approved', 'rescheduleRequest.decidedAt': new Date(), 'rescheduleRequest.alertPending': true } : {}),
    } })

Appointment.findOneAndUpdate({ _id: appointmentId, business: business._id, status: 'confirmed',
    'rescheduleRequest.id': requestId, 'rescheduleRequest.status': 'pending' }, { $set: {
    'rescheduleRequest.status': 'declined', 'rescheduleRequest.decidedAt': new Date(), 'rescheduleRequest.reason': String(reason).slice(0, 500),
    'rescheduleRequest.alertPending': true, lifecycleNotice: lifecycleMarker(`change_declined_${requestId}`),
  } }, { returnDocument: "after" })

Appointment.updateOne({ _id: appointment._id, business: business._id, status: 'confirmed' }, {
    $set: confirm ? { customerConfirmedAt: new Date() } : { customerRescheduleRequestedAt: new Date() },
  })

Appointment.updateOne({ _id: appointment._id, status: appointment.status }, { $set: {
        'approvalRecovery.reconciled': true, 'approvalRecovery.state': expired ? 'needs_recheck' : 'pending',
      } })

Alert.updateMany({ business: appointment.business, 'metadata.appointmentId': String(appointment._id),
    'metadata.approvalRequest': true, resolvedAt: null }, { $set: {
    resolvedAt: new Date(), status: 'resolved', actionRequired: false,
    resolution: `Appointment ${appointment.status}`, 'metadata.approvalState': appointment.status,
  } })

Alert.updateOne({ _id: alert._id, [`${path}.token`]: token }, { $set: { [path]: {
        state, at: now, retryAt, reason: result?.reason || '', providerMessageId: result?.sid || '',
      } } })

Alert.updateOne({ _id: alert._id, [`${path}.token`]: token }, { $set: { [path]: {
        state: error.deliveryUncertain ? 'uncertain' : 'failed', at: now, reason: String(error.code || error.message).slice(0, 200),
      } } })

Appointment.findOneAndUpdate({ _id: appointmentId, business: business._id,
      status: 'confirmed', 'rescheduleRequest.status': { $ne: 'pending' } }, { $set: {
      customerRescheduleRequestedAt: new Date(), rescheduleRequest: { id: crypto.randomUUID(), status: 'pending',
        startAt, endAt, channel, requestedAt: new Date(), alertPending: true },
    } }, { returnDocument: "after", runValidators: true })

Alert.findOneAndUpdate({ _id: current.alert, business: current.business,
    $or: [{ [`${field}.revision`]: { $exists: false } }, { [`${field}.revision`]: { $lte: current.revision } }],
  }, { $set: { [field]: { status: current.status, updatedAt: current.updatedAt, revision: current.revision } } }, { returnDocument: "after" })

Alert.updateOne({ _id: alert._id, [`${path}.token`]: token }, { $set: { [path]: {
        state, at: now, retryAt, reason: result?.reason || '', providerMessageId: result?.sid || '',
      } } })

Alert.updateOne({ _id: alert._id, [`${path}.token`]: token }, { $set: { [path]: {
        state: error.deliveryUncertain ? 'uncertain' : 'failed', at: now, reason: String(error.code || error.message).slice(0, 200),
      } } })

Conversation.findByIdAndUpdate(
      conversationId,
      {
        $set: {
          aiEnabled: false,
          humanTakeover: true,
          humanTakeoverAt: now,
          humanTakeoverBy: null,
          ...bookingTransitionFields('voice_transfer_accepted'),
          "orchestration.phase": "human_takeover",
          "orchestration.handoffStatus": "acknowledged",
          "orchestration.handoffAcknowledgedAt": now,
        },
      },
      { returnDocument: "after" },
    )

Conversation.findOneAndUpdate(
    {
      _id: conversation._id,
      "bookingState.status": status,
      "bookingState.expiresAt": expiresAt,
      status: "open",
      humanTakeover: { $ne: true },
      aiEnabled: { $ne: false },
    },
    {
      $set: {
        ...bookingTransitionFields('offer_expired'),
        "orchestration.phase": "scheduling",
        "orchestration.lastStateTransitionAt": now,
      },
    },
    { returnDocument: "after" },
  )

Conversation.findOneAndUpdate(
    {
      _id: conversation._id,
      $or: [
        { "lifecycle.recoveryNudgeCount": nudgeCount },
        ...(nudgeCount === 0 ? [{ "lifecycle.recoveryNudgeCount": { $exists: false } }] : []),
      ],
    },
    {
      $set: {
        "lifecycle.recoveryNudgeCount": nextCount,
        "lifecycle.lastLifecycleActionAt": now,
        "lifecycle.nextRecoveryNudgeAt": nextCount >= 2 ? null : new Date(now.getTime() + 18 * 60 * 60000),
      },
    },
    { returnDocument: "after" },
  )

Conversation.updateOne(
      { _id: conversation._id, "lifecycle.recoveryNudgeCount": nextCount },
      {
        $set: {
          "lifecycle.recoveryNudgeCount": nudgeCount,
          "lifecycle.nextRecoveryNudgeAt": new Date(now.getTime() + 60 * 60000),
        },
      },
    )
